function icon(name, size){
  const s = size || 24;
  const svg = ICONS[name] || ICONS.leaf;
  return svg.replace("<svg ", `<svg width="${s}" height="${s}" `);
}

// keyword -> icon mapping for dynamically choosing an icon for a benefit phrase
function iconForPhrase(phrase){
  const p = phrase.toLowerCase();
  if(/gut|digest|lining|barrier/.test(p)) return "leaf";
  if(/immune|shield|resilien|third-party|tested/.test(p)) return "shield";
  if(/muscle|lean|protein|amino/.test(p)) return "muscle";
  if(/energy|metaboli|nitrate|blood flow|pump|endurance/.test(p)) return "bolt";
  if(/sleep|calm|stress/.test(p)) return "moon";
  if(/focus|memory|cognit|brain/.test(p)) return "brain";
  if(/bone|heart|cardio/.test(p)) return "heart";
  if(/hydrat|electrolyte|mineral/.test(p)) return "droplet";
  if(/organic|non-gmo|clean|sustain|grass-fed|source/.test(p)) return "leaf";
  if(/science|clinical|dose|studied|bioavailable/.test(p)) return "flask";
  if(/cfu|strain/.test(p)) return "gem";
  return "flask";
}

