function fmtUSD(n){ return "$" + Number(n).toFixed(2); }
function getProduct(slug){ return VERAXA_PRODUCTS.find(p => p.slug === slug); }
function imgSrc(slug){ return PRODUCT_IMAGES[slug] || ""; }
function starRow(rating){
  const full = Math.round(rating);
  let out = "";
  for(let i=0;i<5;i++){ out += `<span style="opacity:${i<full?1:0.3}">${icon("star",13)}</span>`; }
  return out;
}
function productCardHTML(p){
  return `
  <a class="product-card" href="#/product?slug=${p.slug}">
    <div class="thumb">
      <span class="badge">${p.category}</span>
      <img src="${imgSrc(p.slug)}" alt="${p.name}">
    </div>
    <div class="info">
      <span class="cat">${p.category}</span>
      <h3>${p.name}</h3>
      <div class="stars">${starRow(p.rating)}<span>${p.rating.toFixed(1)} (${p.reviews})</span></div>
      <div class="price-row">
        <span class="from">From</span>
        <span class="price">${fmtUSD(p.price["10"])}<span style="font-size:11px;font-weight:500;color:var(--ink-soft);"> /jar</span></span>
      </div>
      <button class="add-btn" type="button" onclick="event.preventDefault();location.hash='#/product?slug=${p.slug}'">View Product</button>
    </div>
  </a>`;
}

function hydrateIcons(root){
  (root||document).querySelectorAll('[data-icon]').forEach(el=>{
    if(el.dataset.iconDone) return;
    const size = el.getAttribute('data-size') || 26;
    el.insertAdjacentHTML('afterbegin', icon(el.getAttribute('data-icon'), size));
    el.dataset.iconDone = "1";
  });
  (root||document).querySelectorAll('img[data-img]').forEach(el=>{
    el.src = imgSrc(el.getAttribute('data-img'));
  });
}

function mountMobileNav(){
  const btn = document.querySelector(".mobile-toggle");
  const nav = document.querySelector(".main-nav");
  if(!btn || !nav || btn.dataset.bound) return;
  btn.dataset.bound = "1";
  btn.addEventListener("click", () => {
    const open = nav.style.display === "flex";
    nav.style.display = open ? "none" : "flex";
    nav.style.cssText += open ? "" : "position:absolute;top:100%;left:0;right:0;background:var(--cream-light);flex-direction:column;padding:18px 24px;gap:16px;border-bottom:1px solid var(--line);z-index:60;";
  });
}

/* ---------- routing ---------- */
function parseRoute(){
  let hash = location.hash.replace(/^#\/?/, "");
  const [path, qs] = hash.split("?");
  return { path: path || "home", params: new URLSearchParams(qs || "") };
}
function showView(name){
  ["home","shop","product"].forEach(v => {
    document.getElementById("view-"+v).style.display = (v===name ? "" : "none");
  });
  window.scrollTo(0,0);
}
let cartCount = 0;
function router(){
  const { path, params } = parseRoute();
  if(path === "shop"){ showView("shop"); initShop(params); }
  else if(path === "product"){ showView("product"); initProduct(params); }
  else { showView("home"); initHome(); }
  hydrateIcons(document);
  mountMobileNav();
}

/* ---------- home ---------- */
function initHome(){
  const heroBadgeData = [
    {icon:"leaf", title:"Premium Ingredients", text:"Sourced for purity and potency"},
    {icon:"flask", title:"Science Backed", text:"Formulas rooted in clinical research"},
    {icon:"shield", title:"Third-Party Tested", text:"For quality, safety and transparency"},
  ];
  document.querySelectorAll("#view-home .hero-badges .hb").forEach((el,i)=>{
    const d = heroBadgeData[i];
    el.innerHTML = `<span>${icon(d.icon,26)}</span><strong>${d.title}</strong><span>${d.text}</span>`;
  });
  const bestSellerSlugs = ["digestive-wellness-support","20-billion-cfu-probiotic-blend","grass-fed-whey-protein","balanced-nutrition-protein-powder"];
  document.getElementById("bestsellers-grid").innerHTML = bestSellerSlugs.map(s => productCardHTML(getProduct(s))).join("");
}

/* ---------- shop ---------- */
const categories = ["All", "Gut Health", "Performance", "Protein & Nutrition", "Vitamins & Minerals", "Superfoods"];
let shopState = { category: "All", bestsellers: false };
function initShop(params){
  shopState.category = params.get("category") || "All";
  shopState.bestsellers = params.get("sort") === "bestsellers";
  renderShopFilters();
  renderShopGrid();
}
function renderShopFilters(){
  document.getElementById("filter-row").innerHTML = categories.map(c =>
    `<button class="filter-chip ${c===shopState.category?"active":""}" data-cat="${c}">${c}</button>`
  ).join("");
  document.querySelectorAll(".filter-chip").forEach(btn=>{
    btn.addEventListener("click", ()=>{
      shopState.category = btn.getAttribute("data-cat");
      renderShopFilters();
      renderShopGrid();
    });
  });
}
function renderShopGrid(){
  let list = VERAXA_PRODUCTS.slice();
  if(shopState.category !== "All"){ list = list.filter(p => p.category === shopState.category); }
  if(shopState.bestsellers){ list.sort((a,b) => (b.rating*Math.log(b.reviews+1)) - (a.rating*Math.log(a.reviews+1))); }
  else { list.sort((a,b) => a.name.localeCompare(b.name)); }
  document.getElementById("shop-grid").innerHTML = list.map(productCardHTML).join("");
}

/* ---------- product ---------- */
const TIER_META = {
  "1":  { label: "1 UNIT",   tag: "" },
  "3":  { label: "3 UNITS",  tag: "Most Popular" },
  "5":  { label: "5 UNITS",  tag: "Best Value" },
  "10": { label: "10 UNITS", tag: "Max Savings" },
};
const SEAL_DATA = [
  { icon: "flag",     label: "Manufactured in the USA" },
  { icon: "badge",    label: "GMP-Certified Facility" },
  { icon: "shield",   label: "Third-Party Tested" },
  { icon: "leaf",     label: "Non-GMO Ingredients" },
  { icon: "wheatOff", label: "Gluten-Free Formula" },
];
let product = null;
let selectedTier = "5";
function tierTotal(tier){ return product.price[tier] * Number(tier); }
function savePct(tier){
  const base = product.price["1"];
  const per = product.price[tier];
  return Math.round((1 - per/base) * 100);
}
function initProduct(params){
  product = getProduct(params.get("slug")) || VERAXA_PRODUCTS.find(p=>p.slug==="balanced-nutrition-protein-powder");
  selectedTier = "5";
  document.title = product.name + " — Veraxa";

  document.getElementById("breadcrumb").innerHTML =
    `<a href="#/">Home</a><span class="sep">/</span>` +
    `<a href="#/shop?category=${encodeURIComponent(product.category)}">${product.category}</a>` +
    `<span class="sep">/</span><span class="current">${product.name}</span>`;

  const img = imgSrc(product.slug);
  document.getElementById("gallery-image").src = img;
  document.getElementById("gallery-image").alt = product.name;

  document.getElementById("p-name").textContent = product.name;
  document.getElementById("p-stars").innerHTML = starRow(product.rating);
  document.getElementById("p-rating-text").textContent = `(${product.reviews})`;
  document.getElementById("p-subtitle").textContent = product.tagline;

  document.getElementById("p-benefits").innerHTML = product.benefits.map(b =>
    `<div class="ib">${icon(iconForPhrase(b),26)}<span>${b}</span></div>`
  ).join("");

  renderQtyTable();

  document.getElementById("seal-strip").innerHTML = SEAL_DATA.map(s =>
    `<div class="seal"><span class="seal-icon">${icon(s.icon,24)}</span><span>${s.label}</span></div>`
  ).join("");

  document.getElementById("trust-badges").innerHTML = product.trust_badges.map(b =>
    `<li>${icon("checkCircle",14)}<span><strong>${b.title}.</strong> ${b.desc}</span></li>`
  ).join("");

  const acc = [
    { title: "Description", body: `<p>${product.description}</p>` },
    { title: "Ingredients", body: `<p>${product.ingredients}</p>` },
    { title: "How to Use", body: `<p>${product.how_to_use}</p><p>Size: ${product.size} &middot; ${product.servings}${product.flavor ? " &middot; Flavor: "+product.flavor : ""}</p>` },
    { title: "Shipping &amp; Returns", body: `<p>Free standard shipping on orders over $125. Orders ship within 1–2 business days. Not fully satisfied? Return any unopened product within 30 days for a full refund.</p>` },
  ];
  document.getElementById("accordion").innerHTML = acc.map((a,i) =>
    `<details ${i===0?"open":""}><summary>${a.title}</summary><div class="acc-body">${a.body}</div></details>`
  ).join("");

  const stackProducts = (product.stack || []).map(getProduct).filter(Boolean);
  document.getElementById("stack-grid").innerHTML = stackProducts.map(productCardHTML).join("");
}
function renderQtyTable(){
  const el = document.getElementById("qty-table");
  el.innerHTML = ["1","3","5","10"].map(tier => {
    const meta = TIER_META[tier];
    const per = product.price[tier];
    const total = tierTotal(tier);
    const save = savePct(tier);
    return `
    <div class="qty-card ${tier===selectedTier?"selected":""}" data-tier="${tier}">
      ${save>0 ? `<span class="save-pill">SAVE ${save}%</span>` : ``}
      <span class="qc-label">${meta.label}</span>
      <span class="qc-tag">${meta.tag}</span>
      <span class="qc-total">${fmtUSD(total)}</span>
      <span class="qc-per">${fmtUSD(per)} / unit</span>
    </div>`;
  }).join("");
  document.querySelectorAll(".qty-card").forEach(opt => {
    opt.addEventListener("click", () => {
      selectedTier = opt.getAttribute("data-tier");
      renderQtyTable();
      updateCartTotal();
    });
  });
  updateCartTotal();
}
function updateCartTotal(){
  const total = tierTotal(selectedTier);
  document.getElementById("purchase-price").textContent = fmtUSD(total);
  document.getElementById("cart-total").textContent = fmtUSD(total);
}

document.addEventListener("click", (e) => {
  if(e.target && e.target.id === "add-to-cart"){
    cartCount += Number(selectedTier);
    document.getElementById("cart-count").textContent = cartCount;
    const btn = e.target;
    const original = btn.innerHTML;
    btn.innerHTML = "ADDED TO CART ✓";
    setTimeout(()=>{ btn.innerHTML = original; }, 1400);
  }
});

window.addEventListener("hashchange", router);
document.addEventListener("DOMContentLoaded", router);